// Fonctions Firestore pour les films
import { db, auth } from "./firebase";
import {
  doc, getDoc, setDoc, updateDoc, deleteDoc, deleteField, getDocs, collection, writeBatch,
} from "firebase/firestore";

function movieRef(movieId) {
  const uid = auth.currentUser.uid;
  return doc(db, "users", uid, "movies", String(movieId));
}

// Lit le document Firestore canonique d'un film (note, commentaire, statut…).
// Renvoie null si le film n'a jamais été ajouté (jamais vu, jamais noté).
export async function getMovieDoc(movieId) {
  const snap = await getDoc(movieRef(movieId));
  return snap.exists() ? snap.data() : null;
}

// Ajoute/met à jour un film. status: "watched" | "watchlist"
export async function saveMovie(movie, status, watchedDate = null) {
  const data = {
    id: movie.id,
    title: movie.title,
    poster_path: movie.poster_path || null,
    release_date: movie.release_date || null,
    runtime: movie.runtime || null,
    status,
    watchedDate: watchedDate || null,
    addedAt: Date.now(),
  };
  // genre_ids peut venir directement d'un résultat de recherche TMDB, ou
  // être dérivé de "genres" (fiche complète). On ne l'écrit que si connu,
  // pour ne jamais écraser une valeur déjà enregistrée par du vide.
  const genreIds = movie.genre_ids || (movie.genres ? movie.genres.map((g) => g.id) : null);
  if (genreIds && genreIds.length > 0) data.genre_ids = genreIds;

  await setDoc(movieRef(movie.id), data, { merge: true });
}

export async function removeMovie(movieId) {
  await deleteDoc(movieRef(movieId));
}

// Nombre de fois où le film a été REVU (en plus du premier visionnage).
// 0 ou absent = vu une seule fois. 1 = revu une fois (affiché "×2"), etc.
export async function setMovieRewatchCount(movieId, count) {
  await updateDoc(movieRef(movieId), {
    rewatchCount: count > 0 ? count : deleteField(),
  });
}

// Remet un film "vu" en liste à voir (annule le visionnage et le compteur
// de revisionnage). La note/le commentaire existants sont conservés.
export async function unwatchMovie(movieId) {
  await updateDoc(movieRef(movieId), {
    status: "watchlist",
    watchedDate: deleteField(),
    rewatchCount: deleteField(),
  });
}

export async function getAllMovies() {
  const uid = auth.currentUser.uid;
  const snap = await getDocs(collection(db, "users", uid, "movies"));
  return snap.docs.map((d) => d.data());
}

export async function importMoviesBatch(moviesData) {
  const uid = auth.currentUser.uid;
  const batch = writeBatch(db);
  moviesData.forEach((m) => {
    const ref = doc(db, "users", uid, "movies", String(m.id));
    batch.set(ref, m, { merge: true });
  });
  await batch.commit();
}

// Note (1-5) + commentaire pour un film. Marque le film comme vu.
// `movie` est optionnel : s'il est fourni (titre/affiche/date), on crée
// proprement le document au cas où le film n'existait pas encore en base.
//
// La date de visionnage n'est posée qu'UNE SEULE FOIS, à la première note :
// si le film a déjà une watchedDate enregistrée (ex. on modifie juste le
// commentaire plus tard), on la conserve telle quelle plutôt que de la
// remplacer par la date du jour à chaque sauvegarde.
export async function setMovieRating(movieId, note, comment, movie = null) {
  const existingSnap = await getDoc(movieRef(movieId));
  const existing = existingSnap.exists() ? existingSnap.data() : null;
  const watchedDate = (existing && existing.watchedDate) || new Date().toISOString().slice(0, 10);

  const data = {
    id: movie ? movie.id : movieId,
    note: note || null,
    comment: comment || "",
    status: "watched",       // noter = vu
    watchedDate,
    ratedAt: Date.now(),
  };
  if (movie) {
    // Renseigné uniquement si connu, pour ne pas écraser d'infos existantes
    if (movie.title != null) data.title = movie.title;
    if (movie.poster_path !== undefined) data.poster_path = movie.poster_path || null;
    if (movie.release_date !== undefined) data.release_date = movie.release_date || null;
    if (movie.runtime !== undefined && movie.runtime != null) data.runtime = movie.runtime;
    const genreIds = movie.genre_ids || (movie.genres ? movie.genres.map((g) => g.id) : null);
    if (genreIds && genreIds.length > 0) data.genre_ids = genreIds;
    if (data.addedAt === undefined) data.addedAt = Date.now();
  }
  // setDoc + merge : crée le document s'il n'existe pas, sinon met à jour.
  await setDoc(movieRef(movieId), data, { merge: true });
}

export async function removeMovieRating(movieId) {
  await updateDoc(movieRef(movieId), {
    note: deleteField(),
    comment: deleteField(),
  });
}

// Renseigne les genres d'un film après coup. Utilisé en rattrapage pour les
// films ajoutés/notés avant l'ajout de cette fonctionnalité.
export async function setMovieGenres(movieId, genreIds) {
  if (!genreIds || genreIds.length === 0) return;
  await updateDoc(movieRef(movieId), { genre_ids: genreIds });
}
